  'consignments',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    forwarderId: uuid('forwarder_id')
      .notNull()
      .references(() => forwarders.id, { onDelete: 'cascade' }),
    reference: varchar('reference', { length: 32 }).notNull(),
