      .notNull()
      .references(() => forwarders.id, { onDelete: 'cascade' }),
    laneCode: varchar('lane_code', { length: 32 }).notNull(),
    carrierCode: varchar('carrier_code', { length: 16 }).notNull(),
    serviceLevel: varchar('service_level', { length: 24 }).notNull(),
