import express from 'express';
import cookieParser from 'cookie-parser';

import { carrierStatusRouter } from './webhooks/carrier-status.js';

const cookieSecret = process.env.COOKIE_SECRET;
if (!cookieSecret) {
  throw new Error('COOKIE_SECRET is not set');
}

export const app = express();

app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use(cookieParser(cookieSecret));
// The carrier callbacks verify an HMAC over the exact bytes they signed,
// so they are mounted before the JSON body parser.
app.use(carrierStatusRouter);
app.use(express.json({ limit: '256kb' }));

app.get('/healthz', (_req, res) => {
  res.json({ ok: true });
});

app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  console.error('unhandled request failure', err);
  res.status(500).json({ error: 'internal_error' });
});

